'use client';

import * as React from 'react';

import { Button } from '@/components/ui/button';
import { hasFeature } from '@/components/ui/billing-kit/providers';
import { type BannerState, BillingStatusBanner } from '@/components/ui/billing-kit/status';
import { useBillingAccount } from '@/components/ui/billing-account/billing-account-context';

/** The account's one current notice, wired to the next step for each state. */
export function AccountBanner({ className }: { className?: string }) {
	const { data, views, subscription, lifecycle, planName, emit, setView, canManage } = useBillingAccount();
	const openInvoice = data.invoices.find((invoice) => invoice.status === 'open');
	const portal = hasFeature(data.provider, 'customerPortal');

	const actions = (state: BannerState): React.ReactNode => {
		if (!canManage) return null;
		switch (state) {
			case 'grace':
				return portal ? (
					<Button size="xs" onClick={() => emit({ type: 'open-portal' })}>
						Update payment method
					</Button>
				) : null;
			case 'suspended':
				return (
					<>
						{openInvoice ? (
							<Button size="xs" onClick={() => emit({ type: 'pay-invoice', invoiceId: openInvoice.id })}>
								Pay open invoice
							</Button>
						) : null}
						{views.includes('credits') ? (
							<Button size="xs" variant="outline" onClick={() => setView('credits')}>
								Add credits
							</Button>
						) : null}
					</>
				);
			case 'review_required':
			case 'admin_hold':
				return (
					<Button size="xs" variant="outline" onClick={() => emit({ type: 'contact-support' })}>
						Contact support
					</Button>
				);
			case 'scheduled_change':
				return (
					<Button size="xs" variant="outline" onClick={() => emit({ type: 'cancel-scheduled-change' })}>
						Keep {subscription ? planName(subscription.planId) : 'current plan'}
					</Button>
				);
			case 'unsubscribed':
			case 'ended':
				return views.includes('plans') ? (
					<Button size="xs" onClick={() => setView('plans')}>
						Choose a plan
					</Button>
				) : null;
			default:
				return null;
		}
	};

	return (
		<BillingStatusBanner
			lifecycle={lifecycle}
			subscription={subscription}
			planName={planName}
			databases={data.databases}
			renderActions={actions}
			className={className}
		/>
	);
}

'use client';

import { Building2, Check, LifeBuoy, LogOut, Settings2, Ticket, User } from 'lucide-react';

import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator } from '@/components/ui/dropdown-menu';
import { AppearanceRow, monogram, SwitcherTrigger } from '@/components/ui/workspace-kit/menu';
import { useBillingAccount } from '@/components/ui/billing-account/billing-account-context';

const ITEM_CLASS = 'gap-2 [&_svg]:size-3.5 [&_svg]:text-muted-foreground';

/** Account switcher: every billing account the viewer can see, appearance, and account links. */
export function AccountMenu({ collapsed }: { collapsed: boolean }) {
	const { data, emit, theme, setTheme, canRedeem, openRedeem } = useBillingAccount();
	const current = data.accounts.find((account) => account.id === data.accountId) ?? data.accounts[0];
	return (
		<DropdownMenu>
			<SwitcherTrigger
				label={`Billing account: ${current?.name ?? 'none'}`}
				name={current?.name ?? ''}
				glyph={monogram(current?.name ?? '?')}
				collapsed={collapsed}
			/>
			<DropdownMenuContent align="start" className="w-64">
				<p className="px-2 pt-1 pb-1.5 text-xs text-muted-foreground">Billing accounts</p>
				{/* The list scrolls on its own so Redeem, Appearance and Log out stay reachable however many accounts there are. */}
				<div role="group" aria-label="Billing accounts" className="max-h-64 overflow-y-auto overscroll-contain">
					{data.accounts.map((account) => {
						const Icon = account.kind === 'organization' ? Building2 : User;
						const active = account.id === data.accountId;
						return (
							<DropdownMenuItem key={account.id} className="gap-2" onClick={active ? undefined : () => emit({ type: 'switch-account', accountId: account.id })}>
								<Icon aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
								<span className="min-w-0 flex-1">
									<span title={account.name} className="line-clamp-2 block [overflow-wrap:anywhere]">
										<bdi>{account.name}</bdi>
									</span>
									<span className="block truncate text-xs text-muted-foreground">
										{account.planName ?? 'No plan'}
										{account.role ? ` · ${account.role}` : ''}
									</span>
								</span>
								{active ? <Check aria-hidden="true" className="size-3.5 shrink-0" /> : null}
							</DropdownMenuItem>
						);
					})}
				</div>
				<DropdownMenuSeparator />
				{canRedeem ? (
					<>
						<DropdownMenuItem className={ITEM_CLASS} onClick={openRedeem}>
							<Ticket aria-hidden="true" />
							Redeem a code
						</DropdownMenuItem>
						<DropdownMenuSeparator />
					</>
				) : null}
				<AppearanceRow value={theme} onChange={setTheme} />
				<DropdownMenuSeparator />
				<DropdownMenuItem className={ITEM_CLASS} onClick={() => emit({ type: 'account-menu', item: 'account-settings' })}>
					<Settings2 aria-hidden="true" />
					Account settings
				</DropdownMenuItem>
				<DropdownMenuItem className={ITEM_CLASS} onClick={() => emit({ type: 'account-menu', item: 'support' })}>
					<LifeBuoy aria-hidden="true" />
					Support
				</DropdownMenuItem>
				<DropdownMenuSeparator />
				<DropdownMenuItem className={ITEM_CLASS} onClick={() => emit({ type: 'account-menu', item: 'log-out' })}>
					<LogOut aria-hidden="true" />
					Log out
				</DropdownMenuItem>
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

'use client';

import { Activity } from 'lucide-react';
import * as React from 'react';

import { LedgerTimeline } from '@/components/ui/billing-kit/ledger';
import { type LedgerClass } from '@/components/ui/billing-kit/types';
import { FilterGroup, ViewFrame } from '@/components/ui/workspace-kit/primitives';
import { startViewTransition, ViewAnimation } from '@/components/ui/workspace-kit/view-transition';
import { useBillingAccount } from '@/components/ui/billing-account/billing-account-context';

type Filter = 'all' | LedgerClass;

/** The ledger, filterable by class: usage, grants, adjustments, refunds. */
export function BillingActivityView() {
	const { data } = useBillingAccount();
	const [filter, setFilter] = React.useState<Filter>('all');
	const count = (value: Filter) => (value === 'all' ? data.ledger.length : data.ledger.filter((entry) => entry.ledgerClass === value).length);
	const entries = filter === 'all' ? data.ledger : data.ledger.filter((entry) => entry.ledgerClass === filter);
	const options = (
		[
			{ value: 'all', label: 'All' },
			{ value: 'usage', label: 'Usage' },
			{ value: 'grant', label: 'Grants' },
			{ value: 'adjustment', label: 'Adjustments' },
			{ value: 'refund', label: 'Refunds' },
		] as const
	)
		.map((option) => ({ ...option, count: count(option.value) }))
		.filter((option) => option.value === 'all' || option.count > 0);

	return (
		<ViewFrame icon={Activity} title="Activity" maxWidth="max-w-3xl">
			<FilterGroup label="Entry type" value={filter} options={options} onChange={(next) => startViewTransition(() => setFilter(next))} />
			<ViewAnimation>
				<div key={filter}>
					<LedgerTimeline entries={entries} meters={data.meters} />
				</div>
			</ViewAnimation>
		</ViewFrame>
	);
}

'use client';

import * as React from 'react';

import type { DescribeTarget } from '@/components/ui/billing-kit/codes';
import type { BillingLifecycle, CreditPack, Meter, Plan, RedeemResult, Subscription, UsageAlert } from '@/components/ui/billing-kit/types';
import type { BillingAccountAction, BillingAccountData, BillingAccountTheme, BillingAccountView } from '@/components/ui/billing-account/types';

export type BillingAccountContextValue = {
	data: BillingAccountData;
	view: BillingAccountView;
	/** Views this host can back, in navigation order. */
	views: BillingAccountView[];
	setView: (view: BillingAccountView) => void;
	emit: (action: BillingAccountAction) => void;
	theme: BillingAccountTheme;
	setTheme: (theme: BillingAccountTheme) => void;
	/** The plan the account is on, after any local change. */
	plan: Plan | undefined;
	subscription: Subscription | undefined;
	lifecycle: BillingLifecycle;
	alerts: UsageAlert[];
	setAlerts: (alerts: UsageAlert[]) => void;
	/** False for members who can see billing but not change it. */
	canManage: boolean;
	planName: (planId: string) => string;
	meterBySlug: ReadonlyMap<string, Meter>;
	meterName: (slug: string) => string;
	/** Opens the change preview for a plan (or asks the host to talk to sales). */
	choosePlan: (plan: Plan, interval?: 'month' | 'year') => void;
	buyPack: (pack: CreditPack) => void;
	pendingPackId: string | undefined;
	/** True when the host can redeem codes and the viewer may use them. */
	canRedeem: boolean;
	openRedeem: () => void;
	/** Redeems through the host and shows the grant locally once it resolves. */
	redeemCode: (code: string) => Promise<RedeemResult>;
	describeTarget: DescribeTarget;
	openMeter: (slug: string) => void;
};

export const BillingAccountContext = React.createContext<BillingAccountContextValue | null>(null);

export function useBillingAccount() {
	const context = React.useContext(BillingAccountContext);
	if (!context) throw new Error('Billing account parts must be rendered inside <BillingAccount>.');
	return context;
}

'use client';

import * as React from 'react';

import { useControllableState } from '@/hooks/use-controllable-state';
import { RedeemCodeDialog, targetDescriber } from '@/components/ui/billing-kit/codes';
import { BillingFormatProvider } from '@/components/ui/billing-kit/context';
import { humanize } from '@/components/ui/billing-kit/format';
import { PlanChangeDialog, type PlanChangeRequest } from '@/components/ui/billing-kit/plan-change-dialog';
import type { BillingLifecycle, CreditPack, Plan, RedeemResult, Subscription, UsageAlert } from '@/components/ui/billing-kit/types';
import { MeterDetailSheet } from '@/components/ui/billing-kit/usage';
import { WorkspaceShell } from '@/components/ui/workspace-kit/shell';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { BillingActivityView } from '@/components/ui/billing-account/activity-view';
import { BillingAccountContext, type BillingAccountContextValue } from '@/components/ui/billing-account/billing-account-context';
import { BillingCreditsView } from '@/components/ui/billing-account/credits-view';
import { BillingInvoicesView } from '@/components/ui/billing-account/invoices-view';
import { BillingOverviewView } from '@/components/ui/billing-account/overview-view';
import { BillingPlansView } from '@/components/ui/billing-account/plans-view';
import { BillingAccountSidebar } from '@/components/ui/billing-account/sidebar';
import type { BillingAccountAction, BillingAccountData, BillingAccountTheme, BillingAccountView } from '@/components/ui/billing-account/types';
import { applyRedemption, type RedeemableState } from '@/components/ui/billing-account/redemption';
import { BillingUsageView } from '@/components/ui/billing-account/usage-view';

type BillingAccountProps = {
	data: BillingAccountData;
	/** Controlled view. Pair with `onViewChange` to sync with a router. */
	view?: BillingAccountView;
	defaultView?: BillingAccountView;
	onViewChange?: (view: BillingAccountView) => void;
	/** Views the host can back, e.g. only `overview` and `plans` without balances or a ledger. Defaults to all six. */
	views?: BillingAccountView[];
	/**
	 * Makes a plan change. `request.checkout` means the host should open the
	 * provider's hosted checkout; resolve once it has been handed off. Reject
	 * with an Error to keep the preview open with its message.
	 */
	onChangePlan?: (request: PlanChangeRequest) => Promise<void> | void;
	/** Starts a credit-pack purchase, usually a hosted checkout. */
	onBuyCredits?: (pack: CreditPack) => Promise<void> | void;
	/**
	 * Redeems a normalised code for this account. Resolve with the result: the
	 * redemption (what it granted) or a typed refusal. Without it, redeeming is
	 * hidden.
	 */
	onRedeemCode?: (code: string) => Promise<RedeemResult>;
	/** Opens the redeem dialog prefilled, e.g. from a `?code=` promo link. */
	initialRedeemCode?: string;
	onAlertsChange?: (alerts: UsageAlert[]) => void;
	/** Receives every control the template renders but does not own. */
	onAction?: (action: BillingAccountAction) => void;
	theme?: BillingAccountTheme;
	onThemeChange?: (theme: BillingAccountTheme) => void;
	/** Formatting. Pass `now` from the server so relative dates hydrate identically. */
	locale?: string;
	timeZone?: string;
	now?: string;
	defaultSidebarCollapsed?: boolean;
	/** Shows the workspace as a rounded frame on a canvas instead of filling its container. */
	framed?: boolean;
	className?: string;
};

const ALL_VIEWS: BillingAccountView[] = ['overview', 'usage', 'plans', 'credits', 'invoices', 'activity'];

type LocalState = RedeemableState & {
	subscription?: Subscription;
	lifecycle?: BillingLifecycle;
	planId?: string;
	alerts: UsageAlert[];
};

const initialState = (data: BillingAccountData): LocalState => ({
	subscription: data.subscription,
	lifecycle: data.lifecycle ?? data.subscription?.lifecycle,
	planId: data.planId ?? data.subscription?.planId ?? data.plans.find((plan) => plan.fallback)?.id,
	alerts: data.alerts,
	balances: data.balances,
	grants: data.grants,
	limits: data.limits,
	ledger: data.ledger,
	redemptions: data.redemptions ?? [],
});

/**
 * Billing Account template: the customer side of Constructive billing. An
 * account switcher and six views (overview, usage, plans, credits, invoices,
 * activity) over one account's plans, meters, credits, ledger, and invoices.
 * The template owns navigation, previews, and optimistic local state; the host
 * owns every purchase, provider hand-off, and persistence call.
 */
function BillingAccount({
	data,
	view: viewProp,
	defaultView = 'overview',
	onViewChange,
	views = ALL_VIEWS,
	onChangePlan,
	onBuyCredits,
	onRedeemCode,
	initialRedeemCode,
	onAlertsChange,
	onAction,
	theme: themeProp,
	onThemeChange,
	locale,
	timeZone,
	now,
	defaultSidebarCollapsed,
	framed,
	className,
}: BillingAccountProps) {
	const viewsKey = views.join('|');
	// Hosts often pass `views` inline; key it by content so the context stays stable.
	const stableViews = React.useMemo(() => viewsKey.split('|') as BillingAccountView[], [viewsKey]);
	const [requestedView, setView] = useControllableState<BillingAccountView>({ prop: viewProp, defaultProp: defaultView, onChange: onViewChange });
	const view = stableViews.includes(requestedView) ? requestedView : (stableViews[0] ?? 'overview');
	const [theme, setTheme] = useControllableState<BillingAccountTheme>({ prop: themeProp, defaultProp: 'system', onChange: onThemeChange });
	const [local, setLocal] = React.useState<LocalState>(() => initialState(data));
	const [source, setSource] = React.useState(data);
	if (source !== data) {
		setSource(data);
		setLocal(initialState(data));
	}
	const [target, setTarget] = React.useState<{ plan: Plan; interval: 'month' | 'year' } | null>(null);
	const [dialogOpen, setDialogOpen] = React.useState(false);
	// The sheet keeps its last meter while closing so its exit animation has content.
	const [meterSlug, setMeterSlug] = React.useState<string | null>(null);
	const [meterOpen, setMeterOpen] = React.useState(false);
	const [pendingPackId, setPendingPackId] = React.useState<string | undefined>();
	const [redeemOpen, setRedeemOpen] = React.useState(Boolean(initialRedeemCode));
	// A new promo link (a changed prefill) reopens the dialog, adjusted during render.
	const [lastPrefill, setLastPrefill] = React.useState(initialRedeemCode);
	if (lastPrefill !== initialRedeemCode) {
		setLastPrefill(initialRedeemCode);
		if (initialRedeemCode) setRedeemOpen(true);
	}

	const handlers = useLatest({ onAction, onAlertsChange, onBuyCredits, onRedeemCode });

	const plan = data.plans.find((candidate) => candidate.id === local.planId);
	const lifecycle: BillingLifecycle = local.lifecycle ?? 'unsubscribed';
	const account = data.accounts.find((candidate) => candidate.id === data.accountId);
	const canManage = account?.role !== 'member';
	const canRedeem = canManage && Boolean(onRedeemCode);
	// Views read the account's live state: host data plus redemptions shown since it arrived.
	const shownData = React.useMemo<BillingAccountData>(
		() => ({ ...data, balances: local.balances, grants: local.grants, limits: local.limits, ledger: local.ledger, redemptions: local.redemptions }),
		[data, local.balances, local.grants, local.ledger, local.limits, local.redemptions],
	);
	const describeTarget = React.useMemo(() => targetDescriber(data.meters, local.limits), [data.meters, local.limits]);

	const context = React.useMemo<BillingAccountContextValue>(() => {
		const planNames = new Map(data.plans.map((candidate) => [candidate.id, candidate.displayName]));
		const meterBySlug = new Map(data.meters.map((meter) => [meter.slug, meter]));
		const emit = (action: BillingAccountAction) => {
			if (action.type === 'cancel-scheduled-change') {
				setLocal((current) => (current.subscription ? { ...current, subscription: { ...current.subscription, scheduledChange: undefined } } : current));
			}
			handlers.current.onAction?.(action);
		};
		return {
			data: shownData,
			view,
			views: stableViews,
			setView,
			emit,
			theme,
			setTheme,
			plan,
			subscription: local.subscription,
			lifecycle,
			alerts: local.alerts,
			setAlerts: (alerts) => {
				setLocal((current) => ({ ...current, alerts }));
				handlers.current.onAlertsChange?.(alerts);
			},
			canManage,
			planName: (id) => planNames.get(id) ?? humanize(id),
			meterBySlug,
			meterName: (slug) => meterBySlug.get(slug)?.displayName ?? humanize(slug),
			choosePlan: (next, interval = 'month') => {
				if (next.contactSales) {
					emit({ type: 'contact-sales', planId: next.id });
					return;
				}
				setTarget({ plan: next, interval });
				setDialogOpen(true);
			},
			buyPack: async (pack) => {
				setPendingPackId(pack.id);
				try {
					await handlers.current.onBuyCredits?.(pack);
				} finally {
					setPendingPackId(undefined);
				}
			},
			pendingPackId,
			canRedeem,
			openRedeem: () => setRedeemOpen(true),
			describeTarget,
			redeemCode: async (code) => {
				const result = (await handlers.current.onRedeemCode?.(code)) ?? ({ status: 'refused', reason: 'not_eligible' } as const);
				if (result.status === 'redeemed') setLocal((current) => ({ ...current, ...applyRedemption(current, result.redemption) }));
				return result;
			},
			openMeter: (slug) => {
				setMeterSlug(slug);
				setMeterOpen(true);
			},
		};
	}, [canManage, canRedeem, data, describeTarget, handlers, lifecycle, local.alerts, local.subscription, pendingPackId, plan, setTheme, setView, shownData, stableViews, theme, view]);

	const confirmChange = async (request: PlanChangeRequest) => {
		await onChangePlan?.(request);
		setLocal((current) => {
			if (request.checkout) return { ...current, lifecycle: 'checkout_pending' };
			const subscription = current.subscription;
			if (request.timing === 'period_end' && subscription) {
				return {
					...current,
					subscription: {
						...subscription,
						scheduledChange: { planId: request.plan.id, priceId: request.price?.id ?? '', effectiveAt: subscription.currentPeriodEnd, state: 'scheduled' },
					},
				};
			}
			return {
				...current,
				planId: request.plan.id,
				subscription: subscription ? { ...subscription, planId: request.plan.id, priceId: request.price?.id, scheduledChange: undefined } : subscription,
			};
		});
	};

	const meter = meterSlug ? data.meters.find((candidate) => candidate.slug === meterSlug) : undefined;

	return (
		<BillingFormatProvider locale={locale} timeZone={timeZone} now={now}>
			<BillingAccountContext.Provider value={context}>
				<WorkspaceShell
					slot="billing-account"
					className={className}
					defaultSidebarCollapsed={defaultSidebarCollapsed}
					framed={framed}
					sidebar={({ mode, collapsed, onCollapsedChange, onNavigate }) => (
						<BillingAccountSidebar drawer={mode === 'drawer'} collapsed={collapsed} onCollapsedChange={onCollapsedChange} onNavigate={mode === 'drawer' ? onNavigate : undefined} />
					)}
				>
					{view === 'overview' ? <BillingOverviewView /> : null}
					{view === 'usage' ? <BillingUsageView /> : null}
					{view === 'plans' ? <BillingPlansView /> : null}
					{view === 'credits' ? <BillingCreditsView /> : null}
					{view === 'invoices' ? <BillingInvoicesView /> : null}
					{view === 'activity' ? <BillingActivityView /> : null}
				</WorkspaceShell>
				<PlanChangeDialog
					open={dialogOpen}
					onOpenChange={setDialogOpen}
					currentPlan={plan}
					targetPlan={target?.plan}
					interval={target?.interval ?? 'month'}
					subscription={local.subscription}
					rows={data.comparisonRows}
					limits={local.limits}
					balances={local.balances}
					provider={data.provider}
					onConfirm={confirmChange}
				/>
				<MeterDetailSheet
					open={meterOpen}
					onOpenChange={setMeterOpen}
					meter={meter}
					balance={local.balances.find((balance) => balance.meterSlug === meterSlug)}
					pool={meter?.categoryMeter ? data.meters.find((candidate) => candidate.slug === meter.categoryMeter) : undefined}
					rateWindows={data.rateWindows}
					periodEnd={local.subscription?.currentPeriodEnd}
				/>
				{canRedeem ? (
					<RedeemCodeDialog
						open={redeemOpen}
						onOpenChange={setRedeemOpen}
						initialCode={initialRedeemCode}
						accountName={account?.name}
						describe={describeTarget}
						onRedeem={context.redeemCode}
						onViewCredits={view !== 'credits' && stableViews.includes('credits') ? () => setView('credits') : undefined}
					/>
				) : null}
			</BillingAccountContext.Provider>
		</BillingFormatProvider>
	);
}

export { BillingAccount };
export type { BillingAccountProps };

'use client';

import { Coins } from 'lucide-react';

import { RedeemCodeField, RedemptionList } from '@/components/ui/billing-kit/codes';
import { CreditGrantList, CreditPackGrid, CreditWallet } from '@/components/ui/billing-kit/credits';
import { hasFeature } from '@/components/ui/billing-kit/providers';
import { Panel, SectionHeading } from '@/components/ui/billing-kit/surface';
import { ViewFrame } from '@/components/ui/workspace-kit/primitives';
import { useBillingAccount } from '@/components/ui/billing-account/billing-account-context';

/**
 * Credits: the wallet, gift codes (redeem and history), packs to buy, and
 * every grant in the order the waterfall spends it.
 */
export function BillingCreditsView() {
	const { data, buyPack, pendingPackId, canRedeem, redeemCode, describeTarget, canManage, meterName } = useBillingAccount();
	const universal = data.balances.find((balance) => balance.meterSlug === 'universal');
	const checkout = hasFeature(data.provider, 'hostedCheckout');
	const redemptions = data.redemptions ?? [];

	return (
		<ViewFrame icon={Coins} title="Credits">
			<div className={canRedeem && universal ? 'grid grid-cols-1 gap-4 @4xl/view:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]' : 'grid grid-cols-1 gap-4'}>
				{universal ? <CreditWallet balance={universal} grants={data.grants} creditsPerCent={data.creditsPerCent} currency={data.currency} /> : null}
				{canRedeem ? (
					<Panel title="Redeem a code" description="Gift codes add credits, often compute, right away. Each works once per account.">
						<RedeemCodeField onRedeem={redeemCode} describe={describeTarget} />
					</Panel>
				) : null}
			</div>

			{data.packs.some((pack) => pack.active) ? (
